/**
 * Prompt regressions: answering with a page must never justify touching the
 * extension checkout.
 *
 * The guardrail lives in model-facing copy only — the injected prompt preamble
 * and the Agent Skill the model loads — so the copy IS the product here. If a
 * future edit drops the rule, an agent can again build a scratch harness inside
 * this repository (the failure this test exists for). `src/generated/prompt.txt`
 * is generated by `scripts/generate-prompt.mjs`; a stale copy also fails.
 *
 *   node --test test/packaging/guardrails.test.mjs
 */
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { test } from 'node:test'

const root = new URL('../../', import.meta.url)
const read = (path) => readFileSync(new URL(path, root), 'utf8')

const skill = read('skills/intelligent-ui/SKILL.md')
const prompt = read('src/generated/prompt.txt')
const troubleshooting = read('skills/intelligent-ui/references/troubleshooting.md')
const spec = JSON.parse(read('vendor/spec.json'))

test('the skill makes the extension checkout read-only while answering', () => {
  assert.match(skill, /extension checkout[\s\S]{0,160}read-only/i, 'SKILL.md names the checkout rule')
  assert.match(skill, /test\/renderer\/\.build/, 'SKILL.md names the generated build directory')
  assert.match(skill, /temporary directory/i, 'SKILL.md offers the temp-dir alternative')
  assert.match(skill, /render_ui` is the preflight|call is the preflight/i, 'SKILL.md names the tool as preflight')
})

test('the injected prompt preamble carries the same guardrail', () => {
  assert.match(prompt, /only preflight/i, 'the prompt says the tool call is the preflight')
  assert.match(prompt, /extension's own checkout/i, 'the prompt forbids editing the extension checkout')
  assert.match(prompt, /temporary directory/i, 'the prompt offers the temp-dir alternative')
  assert.match(prompt, /separate task the user has to ask for explicitly/i, 'extension development stays an explicit task')
})

test('the troubleshooting reference repeats the guardrail with the failure it prevents', () => {
  assert.match(troubleshooting, /do not build a harness/i, 'the reference has the preflight section')
  assert.match(troubleshooting, /test\/renderer\/\.build/, 'the reference names the build directory')
  assert.match(troubleshooting, /rejected program is never partially rendered/i, 'the reference explains why retrying is safe')
})

test('the enabled-session policy is single-sourced and explicit invocation is a directive', () => {
  assert.match(prompt, /decide the format for each answer/i, 'the prompt makes the model choose page vs text')
  assert.match(prompt, /answer in Markdown when a page would only decorate a short answer/i, 'the prompt names when text wins')
  assert.match(prompt, /there is no default format/i, 'the prompt states that Auto has no default format')
  assert.match(prompt, /judge by whether the page improves understanding/i, 'the prompt names the value criterion')
  assert.match(prompt, /a free layout/i, 'the prompt names the free layout among the session layouts')
  assert.match(prompt, /explicitly invokes the `intelligent-ui` skill/i, 'explicit invocation is a directive in the prompt')
  assert.match(skill, /decision policy is owned by the injected/i, 'the skill points at the single policy source')
  assert.match(skill, /applies it rather than restating it/i, 'the skill applies the policy instead of restating it')
  assert.match(skill, /Draw the mechanism/i, 'the skill carries the mechanism-diagram design rule')
  assert.doesNotMatch(skill, /Render a page when the answer gains from structure/, 'the skill no longer restates the render criteria')
  assert.match(skill, /Explicit invocation is a directive/i, 'the skill states the explicit-invocation directive')
  assert.doesNotMatch(skill, /## When to answer in prose/, 'the skill no longer duplicates the prose policy')
})

test('the layout and spacing contract is single-sourced in the prompt and skill', () => {
  assert.match(prompt, /## Layout and spacing contract/, 'the injected prompt carries the layout contract')
  assert.match(prompt, /Leave `gap` unset on the page root/, 'the contract names the root gap rule')
  assert.match(prompt, /Never create vertical space with `Spacer\(\)`/, 'the contract forbids manual vertical spacers')
  assert.match(skill, /Layout and spacing contract/, 'the Agent Skill carries the same contract')
  assert.match(skill, /Host warns about root gaps/, 'the skill points at the Host warnings')
})

test('component descriptions and their schema copies stay identical', () => {
  const defs = spec.schema.$defs
  const missing = Object.keys(spec.components).filter(name => defs[name] === undefined)
  assert.deepEqual(missing, [], 'every component has a JSON-schema definition')
  for (const [name, entry] of Object.entries(spec.components)) {
    if (defs[name].description !== undefined) {
      assert.equal(defs[name].description, entry.description, `${name}: schema description matches components.copy`)
    }
  }
})

test('the local image-source contract is single-sourced in the prompt, skill and spec', () => {
  assert.match(prompt, /## Image sources/, 'the injected prompt carries the image-source contract')
  assert.match(prompt, /never start a web server or invent an http URL for a local file/i, 'the prompt forbids the static-server workaround')
  assert.match(prompt, /never replaced by an unrelated searched photo/i, 'the prompt states no search fallback for an explicit source')
  assert.match(skill, /Use the file path for an image you already have/i, 'the Agent Skill carries the same rule')
  assert.match(spec.components.Image.description, /workspace-relative/i, 'the vendored spec names workspace-relative paths')
  assert.doesNotMatch(spec.components.Image.description, /if it fails, a photo is found/i, 'the vendored Image description dropped the search fallback')
})

test('the article style and Section/Toc vocabulary stay documented', () => {
  assert.match(skill, /## Answer styles/, 'SKILL.md explains Card/Article/Auto')
  assert.match(skill, /Section`/i, 'SKILL.md names the Section component')
  assert.match(prompt, /Section\(title: string/, 'the injected prompt carries the Section signature')
  assert.match(prompt, /Toc\(items: string\[\], anchors\?: string\[\]\)/, 'the injected prompt carries the Toc anchors signature')
  assert.match(prompt, /Auto-chosen, an authorized on-demand result or a selected free template — page shape and typography guidance is advisory/)
  assert.match(skill, /Free template/)
  assert.match(skill, /styleId.*without `temporaryStyle`/)
  assert.match(skill, /style: <"card"\|"article"\|"free">/)
  assert.match(skill, /If the layout is materially unclear, ask one focused layout question/)
  assert.match(read('skills/intelligent-ui/references/components.md'), /\*\*57 components\*\*/, 'the reference header carries the new component count')
})
